p.p("برای مسافر، توصیهٔ من ساده است: اگر به آلودگی هوا حساس هستید یا کودک و سالمند همراه دارید، اقامتگاه را دورتر از حاشیهٔ پالایشگاه انتخاب کنید و در روزهایی که باد به سمت شهر می‌وزد، برنامه‌های بیرونی را کوتاه‌تر بگیرید.")
p.p("توصیهٔ من برای سفر به آبادان: پاییز و زمستان را انتخاب کنید، در تابستان از ظهر تا عصر بیرون نمانید، آب آشامیدنی بسته‌بندی همراه داشته باشید و اقامتگاه را در محله‌های مرکزی و نزدیک خیابان‌های اصلی بگیرید تا رفت‌وآمد شبانه ساده‌تر باشد.")
p.p("برداشت کلی من این است که آبادان آرام‌آرام دارد خودش را دوباره می‌سازد؛ با پروژه‌هایی که بعضی هنوز روی کاغذند، اما با مردمی که به گفتهٔ فرماندار شهر، تجربهٔ صدسالهٔ زندگی با صنعت و توسعه را پشت سر دارند.", BOULEVARD)
add["abadan-269"] = spec(p, 1078, "2026-11-15 09:49:04")

# -------------------------------------------------------------- bojnord 71
GOLESTAN = "https://akhbarday.ir/%D9%BE%DB%8C%D8%B4%D8%B1%D9%81%D8%AA-%D9%81%DB%8C%D8%B2%DB%8C%DA%A9%DB%8C-78%D8%AF%D8%B1%D8%B5%D8%AF%DB%8C-%D9%85%D8%AD%D9%88%D8%B1-%D8%A8%D8%AC%D9%86%D9%88%D8%B1%D8%AF-%D8%A8%D9%87-%D8%AC%D9%86%DA%AF/"
TABNAK = "https://www.tabnak.ir/fa/news/1287015"
INTER = "https://www.mehrnews.com/news/6748790"
INTER_IRIB = "https://www.iribnews.ir/fa/news/5716590"
BUSB = "https://www.tinn.ir/%D8%A8%D8%AE%D8%B4-%DA%AF%D9%84%D8%B3%D8%AA%D8%A7%D9%86-117/287549-%D9%85%DB%8C%D9%84%DB%8C%D8%A7%D8%B1%D8%AF-%D8%B1%DB%8C%D8%A7%D9%84-%D8%A8%D8%B1%D8%A7%DB%8C-%D9%86%D9%88%D8%B3%D8%A7%D8%B2%DB%8C-%D9%86%D8%A7%D9%88%DA%AF%D8%A7%D9%86-%D8%B4%D9%87%D8%B1%D8%AF%D8%A7%D8%B1%DB%8C-%D8%A8%D8%AC%D9%86%D9%88%D8%B1%D8%AF-%D8%AC%D8%B0%D8%A8-%D8%B4%D8%AF"
MOFAKHAM = "https://safarmarket.com/blog/attractions/iran/bojnourd/sardar-mofakham-house-bojnurd"
MOF_IQNA = "https://bojnourd.iqna.ir/fa/news/3751787"

p = Page()
p.h2("بجنورد در سال‌های اخیر؛ از جادهٔ جنگل گلستان تا میدان خرمشهر")
p.p("وقتی خبرهای بجنورد را در این سال‌ها مرور می‌کنم، شهری را می‌بینم که مرکز استان است اما هنوز برای رسیدن به آن باید صبور بود. راه‌ها و پروازها کامل نشده‌اند، در عوض داخل شهر پروژه‌های تازه‌ای شروع شده است. هر دو را این‌جا آورده‌ام.")
p.h3("جادهٔ جنگل گلستان؛ مسیری طولانی تا تکمیل")
p.p("مهم‌ترین مسیر ورود به بجنورد از سمت گرگان، محور بجنورد–جنگل گلستان است. در آذر ۱۴۰۰ استاندار خراسان شمالی گفت پیشرفت فیزیکی این محور پس از ۹ سال تنها ۷۸ درصد است و پروژه به دلیل تخصیص نامناسب اعتبار و مطالبات پیمانکاران نیمه‌فعال مانده است.", GOLESTAN)
p.p("در بهمن ۱۴۰۳، ۲۰ کیلومتر از این محور افتتاح شد و مدیرکل راه و شهرسازی استان گفت برای ۲۰ کیلومتر باقی‌مانده حدود هزار و ۵۰۰ میلیارد تومان اعتبار لازم است. پیشنهاد من این است که این مسیر کوهستانی و پرپیچ را در روشنایی روز برانید و در فصل برف، پیش از حرکت وضعیت راه را بپرسید.", TABNAK)
p.p("به گفتهٔ مدیرکل راه و شهرسازی خراسان شمالی، منابع مالی این بخش در سفر رئیس‌جمهور به استان تصویب شده و در صورت تخصیص اعتبار، تا سال بعد به بهره‌برداری می‌رسد. او این محور را یکی از شاهراه‌های ارتباطی میان استان‌های شمالی و شمال‌شرقی کشور دانست که تکمیلش تصادفات را کم و ایمنی سفر را بیشتر می‌کند.", TABNAK)
p.h3("پروازهای نامنظم")
p.p("فرودگاه بجنورد تنها فرودگاه استان است، اما در همان گزارش آذر ۱۴۰۰ آمده بود که به دلیل همکاری نکردن شرکت‌های هواپیمایی یا کمبود ناوگان، پروازها نامنظم‌اند و استاندار خواستار دست‌کم یک پرواز روزانهٔ تهران–بجنورد شده بود. اگر قصد پرواز دارید، برنامه را نزدیک به تاریخ سفر دوباره نگاه کنید و یک گزینهٔ زمینی هم در ذهن داشته باشید.", GOLESTAN)
p.h3("میدان خرمشهر و اتوبوس‌های شهری")
p.p("در داخل شهر، بزرگ‌ترین پروژهٔ تازه تقاطع غیرهمسطح میدان خرمشهر است که در بهمن ۱۴۰۴ با اعتبار ۹ هزار میلیارد ریال کلنگ‌زنی شد و قرار است پیمانکار حدود یک سال بعد آن را به بهره‌برداری برساند. تا آن زمان، اطراف این میدان کارگاهی است و بهتر است مسیرتان را از خیابان‌های جایگزین انتخاب کنید.", INTER, INTER_IRIB)
p.p("به گفتهٔ رئیس کمیسیون برنامه و بودجهٔ شورای شهر، بخشی از اوراق مشارکتی که برای این تقاطع جذب شد، صرف خرید هشت اتوبوس می‌شود. به گزارش شهرداری، ناوگان مطلوب بجنورد ۹۰ دستگاه است و هنوز ۲۵ تا ۳۰ دستگاه دیگر کم دارد؛ پس در ساعت‌های شلوغ، انتظار طولانی در ایستگاه‌ها دور از ذهن نیست.", BUSB)
p.h3("عمارت مفخم؛ نقطهٔ امیدبخش شهر")
p.p("از نگاه گردشگری، عمارت مفخم نقطهٔ امیدبخش بجنورد است. این بنا در آتش‌سوزی سال ۱۳۱۶ سقف سفالی و چوبی خود را از دست داد و در دههٔ ۱۳۷۰ ادارهٔ میراث فرهنگی بجنورد آن را خرید، مرمت کرد و به‌صورت موزه به روی مردم گشود.", MOFAKHAM)
p.p("پس از آسیب‌هایی که زلزله به آن زد هم، موزهٔ مردم‌شناسی عمارت دوباره مرمت و بازگشایی شد و در زمان بازگشایی اعلام شد از ساعت ۹ تا ۱۷ پذیرای بازدیدکنندگان است. من دست‌کم یک ساعت برای دیدن بخش‌های مختلفش در نظر می‌گیرم.", MOF_IQNA, MOFAKHAM)
p.p("جمع‌بندی من: بجنورد شهری آرام با جاذبه‌های تاریخی در دسترس است، اما راه‌های ورودی و حمل‌ونقل عمومی‌اش هنوز کامل نشده‌اند. اقامتگاه را نزدیک مرکز شهر و عمارت مفخم بگیرید تا بیشتر مسیرها را پیاده یا با تاکسی کوتاه بروید.")
add["bojnord-71"] = spec(p, 1011, "2026-11-15 09:49:01")

