BBC = "https://www.bbc.com/persian/articles/c5y0z2gj7eno"
KHOUZ = "https://khouznews.ir/fa/news/317829"
PYNEV = "https://pynevesht.ir/2024/07/13/%D8%AA%D8%A7%D9%84%D8%A7%D8%A8-%D8%A8%D9%86%D8%AF%D9%88%D9%86-%D9%88-%D9%85%DB%8C%D8%A7%D9%86%DA%AF%D8%B1%D8%A7%D9%86-%D8%A7%DB%8C%D8%B0%D9%87-%D8%AF%D8%B1-%D9%85%D8%B3%DB%8C%D8%B1-%D9%81%D8%A7%D8%AC/"
IRANDES = "https://www.irandeserts.com/article/%D8%AA%D8%A7%D9%84%D8%A7%D8%A8-%D9%85%DB%8C%D8%A7%D9%86%DA%AF%D8%B1%D8%A7%D9%86/"
DAPNO = "https://dapno.ir/TourismPlace/1300"
IRANGARD = "https://irangard.com/izeh"

p = Page()
p.h2("ایذه در سال‌های اخیر؛ میراثی کهن و طبیعتی شکننده")
p.p("ایذه از معدود شهرهایی است که نیایشگاه عیلامی، تالاب و دشت‌های کوهستانی را در فاصله‌ای کوتاه کنار هم دارد. اما خبرهای چند سال اخیر نشان می‌دهد همین داشته‌ها تا چه اندازه آسیب‌پذیرند. در این بخش، تصویر امروز ایذه را با پیشرفت‌ها و کمبودهایش آورده‌ام.")
p.h3("اشکفت سلمان؛ میراثی در انتظار ثبت جهانی")
p.p("اشکفت سلمان، نیایشگاه عیلامی ایذه، از سال ۲۰۰۷ در فهرست موقت یونسکو قرار دارد. در یکم شهریور ۱۴۰۴، انجمن دوستداران میراث فرهنگی ایذه خبر داد که با لودر و بدون مجوز در محوطهٔ این اثر خاکبرداری شده است.", BBC)
p.p("این نیایشگاه که با نام معبد تاریشا هم شناخته می‌شود، قدمتی نزدیک به ۳ هزار و ۳۰۰ سال دارد و از آثار دورهٔ عیلامی است؛ یعنی کهن‌تر از بسیاری از بناهایی که معمولاً در سفرهای خوزستان می‌بینیم.", KHOUZ)
p.p("سرپرست میراث فرهنگی ایذه گفت جلوی این کار گرفته شد و رئیس شورای شهر هم اعلام کرد پیمانکار بدون اجازه دست به این کار زده و پروژه متوقف شده است. به نظر من این ماجرا یادآوری است که میراث ایذه هنوز به مراقبت همه نیاز دارد؛ اگر به دیدنش رفتید، از مسیرهای مشخص بیرون نروید و به سنگ‌نگاره‌ها دست نزنید.", KHOUZ, BBC)
p.h3("تالاب میانگران؛ کوچک‌تر از همیشه")
p.p("تالاب میانگران در نزدیکی شهر ایذه یکی از دیدنی‌ترین جاهای شهرستان است، اما در تیر ۱۴۰۳ گزارش شد از حدود ۲ هزار و ۴۴۰ هکتار مساحت آن، تنها ۲۴ درصد، یعنی ۵۷۶ هکتار، آب دارد. فعالان محیط زیست حفر بی‌رویهٔ چاه را از عوامل اصلی این وضعیت می‌دانند.", PYNEV)
p.p("این نخستین بار هم نیست. در سال ۱۳۷۶ مصرف بی‌رویهٔ آب، تالاب را خشک کرد و میلیون‌ها قورباغه به شهر ایذه هجوم آوردند؛ خاطره‌ای که هنوز در گزارش‌های مربوط به این تالاب تکرار می‌شود.", IRANDES)
p.p("تالاب بندون، با وسعتی حدود هزار و ۲۰۰ هکتار در شرق شهر ایذه، کمتر شناخته شده است و بیش از ۱۰ هزار نفر در ۱۰ روستای اطرافش زندگی می‌کنند. فعالان محیط زیست هر دو تالاب را بخشی از پروندهٔ ثبت جهانی ایذه می‌دانند و دربارهٔ تهدید چاه‌های بی‌رویه برای هر دو هشدار داده‌اند.", PYNEV)
p.p("کمبود دیگر این است که در مجاورت تالاب میانگران مرکز اقامتی وجود ندارد و ورود پساب‌های کشاورزی هم آن را تهدید می‌کند. پیشنهاد من این است که میانگران را در سفری روزانه ببینید، بهار یا پاییز بروید، آب و غذا همراه داشته باشید و زباله‌ای پشت سر نگذارید.", DAPNO)
p.h3("نزدیک‌ترین اقامت مناسب")
p.p("برای اقامت در ایذه، هتل، اقامتگاه بوم‌گردی و کمپ در دشت سوسن گزینه‌های رایج‌اند. یکی از اقامتگاه‌های شناخته‌شده، بوم‌گردی الیما در روستای تکاب است که ۷ اتاق و ظرفیت ۳۵ نفر دارد و به آبشار توف سپید دسترسی خوبی دارد.", IRANGARD)
p.p("برای خانواده‌ها، به نظر من ماندن در اقامتگاه‌های رسمی شهر یا روستاهای گردشگری امن‌تر از کمپ کردن در حاشیهٔ تالاب است؛ به‌ویژه شب‌ها که دسترسی به خدمات در این حاشیه‌ها محدود است.")
p.p("جمع‌بندی من: ایذه برای مسافری که به تاریخ عیلامی و طبیعت زاگرس علاقه دارد، مقصدی کم‌نظیر است، اما زیرساخت گردشگری آن هنوز ساده است. با برنامهٔ روزانه، راهنمای محلی و احترام به محوطه‌های تاریخی، سفری امن‌تر و بهتر خواهید داشت.")
